<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { BarChart3, Eye, MousePointerClick, TrendingUp, Users } from '@lucide/vue'; import { api, type Analytics } from '../lib/api'; import { useSessionStore } from '../stores/session'
const session=useSessionStore();const data=ref<Analytics|null>(null);const platform=ref('all');const platforms=computed(()=>[...new Set(data.value?.series.map(i=>i.platform)??[])]);const rows=computed(()=>platform.value==='all'?data.value?.series??[]:data.value?.series.filter(i=>i.platform===platform.value)??[]);const maxReach=computed(()=>Math.max(1,...rows.value.map(i=>i.reach)));onMounted(async()=>data.value=await api.analytics(session.brandId));const number=(v?:number)=>new Intl.NumberFormat('zh-TW').format(v??0)
</script>
<template><div class="page-stack"><section class="page-title-row"><div><p class="eyebrow">PERFORMANCE</p><h2>成效分析</h2><p>以模擬數據回顧內容表現與平台差異。</p></div><select v-model="platform" class="filter-select"><option value="all">全部平台</option><option v-for="item in platforms" :key="item" :value="item">{{item}}</option></select></section><section class="metric-grid analytics"><article><span class="metric-icon coral"><Users/></span><div><small>總觸及</small><strong>{{number(data?.totals.reach)}}</strong></div></article><article><span class="metric-icon blue"><Eye/></span><div><small>總曝光</small><strong>{{number(data?.totals.impressions)}}</strong></div></article><article><span class="metric-icon violet"><TrendingUp/></span><div><small>互動率</small><strong>{{data?.totals.engagementRate??0}}%</strong></div></article><article><span class="metric-icon amber"><MousePointerClick/></span><div><small>連結點擊</small><strong>{{number(data?.totals.clicks)}}</strong></div></article></section><section class="analytics-layout"><article class="panel chart-panel"><div class="panel-head"><div><p class="eyebrow">REACH TREND</p><h3>每日觸及</h3></div></div><div v-if="rows.length" class="bar-chart"><div v-for="row in rows" :key="`${row.metricDate}-${row.platform}`"><span :style="{height:`${Math.max(8,row.reach/maxReach*100)}%`}" :title="`${row.platform}: ${number(row.reach)}`"></span><small>{{row.metricDate.slice(5)}}</small></div></div><div v-else class="empty-block"><BarChart3/><p>發布內容後會產生成效資料</p></div></article><article class="panel"><div class="panel-head"><div><p class="eyebrow">PLATFORM DATA</p><h3>平台明細</h3></div></div><div class="analytics-table"><div class="table-head"><span>日期／平台</span><span>觸及</span><span>互動</span><span>點擊</span></div><div v-for="row in rows" :key="`${row.metricDate}-${row.platform}-table`"><span><strong>{{row.platform}}</strong><small>{{row.metricDate}}</small></span><span>{{number(row.reach)}}</span><span>{{number(row.engagements)}}</span><span>{{number(row.clicks)}}</span></div></div></article></section></div></template>
